content.text:
{
  "name": "UDP组播CAN虚拟总线",
  "name_en": "UDP Multicast CAN Virtual Bus",
  "manufacturer": "",
  "description": "用于实验软件中的非物理虚拟通信组件，通过 IP/UDP 组播在多个进程或主机之间传输 CAN 或 CAN-FD 报文。适合局域网内的分布式测试、仿真和进程间总线消息交换，不对应具体硬件仪器。",
  "description_en": "A non-physical virtual communication component used in lab software to exchange CAN or CAN-FD messages between multiple processes or hosts over IP/UDP multicast. It is suited for distributed testing, simulation, and inter-process bus messaging on a LAN, and does not correspond to a specific hardware instrument.",
  "actions": [
    {
      "action_name": "auto-is_fd",
      "description": "检查是否支持 CAN-FD 帧。",
      "description_en": "Check whether CAN-FD frames are supported."
    },
    {
      "action_name": "auto-send",
      "description": "通过 UDP 组播虚拟总线发送 CAN 或 CAN-FD 报文。",
      "description_en": "Send a CAN or CAN-FD message over the UDP multicast virtual bus."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取内部 UDP 套接字的文件描述符。",
      "description_en": "Get the file descriptor of the internal UDP socket."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭所有套接字并释放相关资源。",
      "description_en": "Close all sockets and release associated resources."
    }
  ],
  "tag_hints": [
    "virtual CAN bus",
    "UDP multicast",
    "CAN-FD messaging",
    "inter-process communication",
    "distributed test systems",
    "LAN multicast"
  ]
}

